import { Activity, BarChart3, BookOpen, CheckCircle2, ChevronRight, CircleHelp, FileCheck2, FileText, Gauge, LayoutDashboard, Menu, MessageSquare, MoreHorizontal, RefreshCw, Search, Settings2, ShieldCheck, SlidersHorizontal, Users, Video, X, XCircle } from "lucide-react";
import { Badge } from "@/components/ui/badge";
import { Button } from "@/components/ui/button";
import { Card, CardContent, CardDescription, CardHeader, CardTitle } from "@/components/ui/card";
import { Input } from "@/components/ui/input";
import { Table, TableBody, TableCell, TableHead, TableHeader, TableRow } from "@/components/ui/table";
import { adminFetch, metricValue, type AdminAnalytics, type AdminChannel, type AdminCommunityComment, type AdminContributor, type AdminCreatorEntitlement, type AdminCreatorMembership, type AdminEventRecord, type AdminFoundingApplication, type AdminInvite, type AdminNotification, type AdminOverview, type AdminPublishedArticle, type AdminPublishedVideo, type AdminProviderStatus, type AdminReport, type AdminRestriction, type AdminRoleSummary, type AdminScraperRun, type AdminTeam, type ClassicComment, type CommunityPost, type Member, type MemberActivity } from "@/lib/api";

type View = "overview" | "analytics" | "activity" | "members" | "roles" | "restrictions" | "community" | "community-content" | "comments" | "reports" | "moderation-history" | "creators" | "founding" | "studio-access" | "channels" | "videos" | "education" | "contributors" | "teams" | "events" | "notifications" | "health" | "security" | "audit" | "settings";
type NavItem = { id: View; label: string; icon: typeof LayoutDashboard };
type NavGroup = { label: string; items: NavItem[] };

const navGroups: NavGroup[] = [
  { label: "Dashboard", items: [{ id: "overview", label: "Overview", icon: LayoutDashboard }, { id: "analytics", label: "Analytics", icon: BarChart3 }, { id: "activity", label: "Activity", icon: Activity }] },
  { label: "Members", items: [{ id: "members", label: "All Members", icon: Users }, { id: "roles", label: "Roles & Permissions", icon: ShieldCheck }, { id: "restrictions", label: "Account Restrictions", icon: SlidersHorizontal }] },
  { label: "Community", items: [{ id: "community", label: "Community Overview", icon: MessageSquare }, { id: "community-content", label: "Posts & Comments", icon: FileText }, { id: "reports", label: "Reports & Moderation", icon: CheckCircle2 }, { id: "moderation-history", label: "Moderation History", icon: FileCheck2 }] },
  { label: "Creators", items: [{ id: "creators", label: "Creator Directory", icon: Users }, { id: "founding", label: "Founding 50", icon: CheckCircle2 }, { id: "studio-access", label: "Creator Studio Access", icon: Video }, { id: "channels", label: "Creator Channels", icon: MoreHorizontal }] },
  { label: "Content & Publishing", items: [{ id: "contributors", label: "Contributor Management", icon: FileText }, { id: "teams", label: "Paranormal Teams", icon: Users }, { id: "education", label: "Education Center", icon: BookOpen }, { id: "comments", label: "Article Comment Moderation", icon: CheckCircle2 }, { id: "videos", label: "TPI Videos", icon: Video }, { id: "events", label: "Events", icon: FileCheck2 }] },
  { label: "System", items: [{ id: "notifications", label: "Notifications", icon: MessageSquare }, { id: "health", label: "Platform Health", icon: Gauge }, { id: "security", label: "Security", icon: ShieldCheck }, { id: "audit", label: "Audit Logs", icon: FileCheck2 }, { id: "settings", label: "System Settings", icon: Settings2 }] },
];
const flatNav = navGroups.flatMap((group) => group.items);

function App() {
  const [view, setView] = useState<View>("overview"); const [sidebarOpen, setSidebarOpen] = useState(false); const [notice, setNotice] = useState(""); const [range, setRange] = useState("30d"); const [overview, setOverview] = useState<AdminOverview | null>(null); const [overviewLoading, setOverviewLoading] = useState(true);
  const loadOverview = () => { setOverviewLoading(true); adminFetch<AdminOverview>(`/admin/overview?range=${range}`).then(setOverview).catch((error) => setNotice(error.message)).finally(() => setOverviewLoading(false)); };
  useEffect(loadOverview, [range]);
  const selectView = (next: View) => { setView(next); setSidebarOpen(false); setNotice(""); };
  const current = flatNav.find((item) => item.id === view) || flatNav[0];
  const implemented = new Set<View>(["overview", "analytics", "activity", "audit", "members", "community", "community-content", "comments", "moderation-history", "contributors", "teams", "health", "creators", "founding", "studio-access", "settings", "education", "videos", "events", "reports", "notifications", "channels", "roles", "restrictions"]);
  return <div className="admin-preview-app">
    <aside className={`admin-preview-sidebar ${sidebarOpen ? "is-open" : ""}`}>
      <div className="admin-preview-brand"><span className="admin-preview-mark">TPI</span><div><strong>Administration Center</strong><small>Protected preview</small></div><button className="mobile-close" onClick={() => setSidebarOpen(false)} aria-label="Close navigation"><X size={18} /></button></div>
      <div className="admin-preview-scope"><ShieldCheck size={16} /><span>Owner / admin session</span></div>
      <nav aria-label="Administration preview navigation">{navGroups.map((group) => <div className="nav-group" key={group.label}><span className="nav-heading">{group.label}</span>{group.items.map((item, index) => <button key={`${group.label}-${item.label}-${index}`} className={view === item.id && !(item.id === "community" && index === 1) ? "nav-item active" : "nav-item"} onClick={() => selectView(item.id)}><item.icon size={16} /><span>{item.label}</span>{view === item.id && <ChevronRight className="nav-chevron" size={15} />}</button>)}</div>)}</nav>
      <div className="admin-preview-sidebar-foot">TPI-ADMIN-007A<br /><span>Protected preview — `/admin-panel` remains unchanged</span></div>
    </aside>
    {sidebarOpen && <button className="sidebar-scrim" onClick={() => setSidebarOpen(false)} aria-label="Close navigation" />}
    <main className="admin-preview-main"><header className="admin-preview-topbar"><button className="mobile-menu" onClick={() => setSidebarOpen(true)} aria-label="Open navigation"><Menu size={20} /></button><div><p className="eyebrow">The Paranormal Initiative</p><h1>{current.label}</h1></div><div className="topbar-status"><span className="status-dot" /> Protected session</div></header>{notice && <div className="preview-notice" role="alert">{notice}</div>}{view === "overview" && <Dashboard overview={overview} loading={overviewLoading} range={range} onRange={setRange} onRefresh={loadOverview} onNavigate={selectView} />}{view === "analytics" && <Analytics range={range} onRange={setRange} onNotice={setNotice} />}{view === "activity" && <ActivityView onNotice={setNotice} />}{["audit", "moderation-history"].includes(view) && <Audit onNotice={setNotice} historyOnly={view === "moderation-history"} />}{view === "members" && <Members onNotice={setNotice} />}{view === "community" && <CommunityOverview overview={overview} onNavigate={selectView} />}{view === "community-content" && <CommunityPosts onNotice={setNotice} />}{view === "comments" && <Comments onNotice={setNotice} />}{view === "contributors" && <Contributors onNotice={setNotice} />}{view === "teams" && <Teams onNotice={setNotice} />}{view === "health" && <PlatformHealth onNotice={setNotice} />}{view === "creators" && <CreatorDirectory onNotice={setNotice} />}{view === "founding" && <Founding50 onNotice={setNotice} />}{view === "studio-access" && <StudioAccess onNotice={setNotice} />}{view === "settings" && <SettingsView onNotice={setNotice} />}{view === "education" && <PublishedEducation onNotice={setNotice} />}{view === "videos" && <PublishedVideos onNotice={setNotice} />}{view === "events" && <ApprovedEvents onNotice={setNotice} />}{view === "reports" && <Reports onNotice={setNotice} />}{view === "notifications" && <Notifications onNotice={setNotice} />}{view === "channels" && <Channels onNotice={setNotice} />}{view === "roles" && <Roles onNotice={setNotice} />}{view === "restrictions" && <Restrictions onNotice={setNotice} />}{!implemented.has(view) && <Capability view={view} overview={overview} />}</main>
  </div>;
}

function Dashboard({ overview, loading, range, onRange, onRefresh, onNavigate }: { overview: AdminOverview | null; loading: boolean; range: string; onRange: (value: string) => void; onRefresh: () => void; onNavigate: (view: View) => void }) {
  const cards: Array<[string, string, string, View]> = [["Members", metricValue(overview?.metrics || {}, "members", "total"), "All contributor accounts", "members"], ["Active members", metricValue(overview?.metrics || {}, "members", "active"), "Active contributor accounts", "members"], ["Community posts", metricValue(overview?.metrics || {}, "communityPosts", "visible"), "Visible Community Feed posts", "community-content"], ["Community comments", metricValue(overview?.metrics || {}, "communityComments", "visible"), "Visible Community Feed comments", "community-content"], ["Reactions", metricValue(overview?.metrics || {}, "communityReactions", "total"), "Community Feed reactions", "community-content"], ["Published videos", metricValue(overview?.metrics || {}, "videos", "published"), "Published TPI Videos", "videos"], ["Creator channels", metricValue(overview?.metrics || {}, "creatorChannels", "total"), "TPI video channels", "channels"], ["Education articles", metricValue(overview?.metrics || {}, "articles", "published"), "Published Education Center articles", "education"], ["Approved teams", metricValue(overview?.metrics || {}, "teams", "approved"), "Approved Paranormal Teams", "teams"], ["Open reports", reportQueueValue(overview?.metrics || {}), "Video + messenger metadata; resolution controls unavailable", "reports"], ["Founding 50 allocated", metricValue(overview?.metrics || {}, "founding50", "allocated"), "No awards are activated by this preview", "founding"]];
  return <section className="content-stack"><div className="page-intro"><div><p className="eyebrow">Authoritative D1 snapshot</p><h2>Operations at a glance</h2><p>Metrics are read from the existing admin API. Missing optional sources stay unavailable; no historical values are fabricated.</p></div><div className="page-actions"><select aria-label="Dashboard range" value={range} onChange={(event) => onRange(event.target.value)}><option value="today">Today</option><option value="7d">7 days</option><option value="30d">30 days</option><option value="90d">90 days</option></select><Button variant="outline" onClick={onRefresh}><RefreshCw size={16} />Refresh</Button></div></div><div className="metric-grid">{cards.map(([label, value, note, target]) => <button className="metric-button" key={label} onClick={() => onNavigate(target)}><Card><CardHeader><CardDescription>{label}</CardDescription><CardTitle className="metric-value">{loading ? "…" : value}</CardTitle></CardHeader><CardContent><span className="metric-note">{note}</span><ChevronRight size={15} /></CardContent></Card></button>)}</div><div className="two-column"><Card><CardHeader><CardTitle>Current boundaries</CardTitle><CardDescription>What this controlled preview can safely do.</CardDescription></CardHeader><CardContent className="status-list"><div><Badge variant="success">Live</Badge><span>Overview, member list/detail, community posts, classic comments, reports metadata, and audit logs</span></div><div><Badge variant="warning">Partial</Badge><span>Creator, publishing, events, settings, and team tools remain bounded integrations</span></div><div><Badge variant="warning">Limited</Badge><span>Reports expose metadata only; unified resolution actions and private evidence remain unavailable</span></div><div><Badge variant="success">Preserved</Badge><span>Owner/admin server gate, Creator Studio gate, `/live-video`, D1, and R2 boundaries</span></div></CardContent></Card><Card><CardHeader><CardTitle>Preview status</CardTitle><CardDescription>{overview?.range ? `${overview.range.start} through ${overview.range.end}` : "Waiting for the protected API"}</CardDescription></CardHeader><CardContent><p className="muted">{overview?.generatedAt ? `Generated ${new Date(overview.generatedAt).toLocaleString()}.` : loading ? "Loading protected data…" : "No overview response was returned."}</p><a className="inline-link" href="#audit" onClick={(event) => { event.preventDefault(); onNavigate("audit"); }}>Open audit activity <ChevronRight size={15} /></a></CardContent></Card></div></section>;
}

function reportQueueValue(metrics: AdminOverview["metrics"]) {
  const video = metrics?.videoReports;
  const messenger = metrics?.messengerReports;
  if (video?.unavailable || messenger?.unavailable) return "Unavailable";
  if (video == null || messenger == null) return "—";
  return (Number(video.total || 0) + Number(messenger.total || 0)).toLocaleString();
}

function CommunityOverview({ overview, onNavigate }: { overview: AdminOverview | null; onNavigate: (view: View) => void }) {
  const cards: Array<[string, string, string]> = [
    ["Visible posts", metricValue(overview?.metrics || {}, "communityPosts", "visible"), "Active Community Feed posts"],
    ["Visible comments", metricValue(overview?.metrics || {}, "communityComments", "visible"), "Active Community Feed comments"],
    ["Reactions", metricValue(overview?.metrics || {}, "communityReactions", "total"), "Community Feed reactions"],
  ];
  return <section className="content-stack"><div className="page-intro"><div><p className="eyebrow">Community Feed</p><h2>Community Overview</h2><p>Authoritative community totals from the protected overview contract. Use Posts &amp; Comments for record-level review and status controls.</p></div><Button variant="outline" onClick={() => onNavigate("community-content")}>Open Posts &amp; Comments <ChevronRight size={16} /></Button></div><div className="metric-grid">{cards.map(([label, value, note]) => <Card key={label}><CardHeader><CardDescription>{label}</CardDescription><CardTitle className="metric-value">{value}</CardTitle></CardHeader><CardContent><span className="metric-note">{note}</span></CardContent></Card>)}</div><Card><CardHeader><CardTitle>Community moderation boundary</CardTitle><CardDescription>Overview and record-level review are intentionally separate resources.</CardDescription></CardHeader><CardContent className="status-list"><div><Badge variant="success">Protected</Badge><span>Totals are read from the existing authenticated administration API.</span></div><div><Badge variant="outline">Posts &amp; Comments</Badge><span>Open the dedicated route for active, hidden, and deleted posts plus metadata-only Community Comments.</span></div><div><Badge variant="outline">Article comments</Badge><span>Classic article comment moderation remains separate under Education Center.</span></div></CardContent></Card></section>;
}

function ActivityView({ onNotice }: { onNotice: (value: string) => void }) {
  type ActivityRow = { id: string; actorUsername: string; actorRole: string; action: string; targetType?: string; targetId?: string; createdAt: string };
  const [rows, setRows] = useState<ActivityRow[]>([]);
  const [loading, setLoading] = useState(true);
  const load = () => {
    setLoading(true);
    adminFetch<{ logs: ActivityRow[] }>("/admin/audit-logs?page=1&limit=25").then((body) => setRows(body.logs || [])).catch((error) => onNotice(error.message)).finally(() => setLoading(false));
  };
  useEffect(load, []);
  return <section className="content-stack"><div className="page-intro"><div><p className="eyebrow">Dashboard</p><h2>Activity</h2><p>Recent protected administrative activity from the existing audit contract. Use Audit Logs for searching and pagination.</p></div><Button variant="outline" onClick={load}><RefreshCw size={16} />Refresh</Button></div><Card><CardHeader><CardTitle>Recent activity</CardTitle><CardDescription>Read-only activity feed; private message bodies, recordings, and stream keys are excluded.</CardDescription></CardHeader><CardContent className="audit-list">{loading ? <LoadingState label="Loading recent activity…" /> : rows.length ? rows.map((row) => <div className="audit-row" key={row.id}><div><strong>{row.action}</strong><span>{row.targetType || "system"}{row.targetId ? ` · ${row.targetId}` : ""}</span></div><div><Badge variant="outline">{row.actorUsername} · {row.actorRole}</Badge><time>{new Date(row.createdAt).toLocaleString()}</time></div></div>) : <EmptyState label="No recent administrative activity returned." icon={<Activity size={28} />} />}</CardContent></Card></section>;
}

function Analytics({ range, onRange, onNotice }: { range: string; onRange: (value: string) => void; onNotice: (value: string) => void }) {
  const [analytics, setAnalytics] = useState<AdminAnalytics | null>(null);
  const [loading, setLoading] = useState(true);
  useEffect(() => {
    let active = true;
    setLoading(true);
    adminFetch<AdminAnalytics>(`/admin/analytics?range=${encodeURIComponent(range)}`)
      .then((body) => { if (active) { setAnalytics(body); onNotice(""); } })
      .catch((error) => { if (active) { setAnalytics(null); onNotice(error instanceof Error ? error.message : "Analytics could not be loaded."); } })
      .finally(() => { if (active) setLoading(false); });
    return () => { active = false; };
  }, [range, onNotice]);
  const rows = useMemo(() => ["members", "communityPosts", "communityComments", "communityReactions", "videos", "events"].map((key) => ({ key, label: key.replace(/([A-Z])/g, " $1"), points: analytics?.trends?.[key], definition: analytics?.definitions?.[key] })), [analytics]);
  return <section className="content-stack"><div className="page-intro"><div><p className="eyebrow">Data-backed trends</p><h2>Analytics</h2><p>Counts are grouped from authoritative timestamps by the protected `/admin/analytics` contract.</p></div><select aria-label="Analytics range" value={range} onChange={(event) => onRange(event.target.value)}><option value="today">Today</option><option value="7d">7 days</option><option value="30d">30 days</option><option value="90d">90 days</option></select></div><div className="analytics-grid">{rows.map(({ key, label, points, definition }) => <TrendCard key={key} label={label} definition={definition} points={points} loading={loading} />)}</div></section>;
}
function TrendCard({ label, definition, points, loading }: { label: string; definition?: string; points: AdminAnalytics["trends"][string] | undefined; loading: boolean }) { const rows = Array.isArray(points) ? points : []; const max = Math.max(1, ...rows.map((point) => point.count)); return <Card><CardHeader><CardTitle className="capitalize">{label}</CardTitle><CardDescription>{definition || "Records grouped by created date"}</CardDescription></CardHeader><CardContent>{loading ? <p className="muted">Loading trend…</p> : rows.length ? <div className="spark-bars" aria-label={`${label} trend`}>{rows.map((point) => <span key={point.day} style={{ height: `${Math.max(8, (point.count / max) * 100)}%` }} title={`${point.day}: ${point.count}`} />)}</div> : <p className="muted">No trend rows are available for this source.</p>}</CardContent></Card>; }

function Members({ onNotice }: { onNotice: (value: string) => void }) {
  const [search, setSearch] = useState(""); const [status, setStatus] = useState(""); const [role, setRole] = useState(""); const [page, setPage] = useState(1); const [sort, setSort] = useState("name"); const [direction, setDirection] = useState<"asc" | "desc">("asc"); const [selected, setSelected] = useState<Member | null>(null); const [activity, setActivity] = useState<MemberActivity | null>(null); const [loadingDetail, setLoadingDetail] = useState(false); const [confirm, setConfirm] = useState<"block" | "unblock" | null>(null);
  const filters = [...(search ? [{ field: "search", operator: "contains" as const, value: search }] : []), ...(status ? [{ field: "status", operator: "eq" as const, value: status }] : []), ...(role ? [{ field: "role", operator: "eq" as const, value: role }] : [])];
  const { result, query } = useList<Member>({ resource: "members", pagination: { currentPage: page, pageSize: 25 }, filters, sorters: [{ field: sort, order: direction }] }); const members = result.data || [];
  const [activityPage, setActivityPage] = useState(1);
  const loadActivity = async (member: Member, requestedPage: number) => { setLoadingDetail(true); try { setActivity(await adminFetch<MemberActivity>(`/admin/members/${encodeURIComponent(member.username)}/activity?page=${requestedPage}&pageSize=25`)); } catch (error) { onNotice((error as Error).message); } finally { setLoadingDetail(false); } };
  const openMember = async (member: Member) => { setSelected(member); setActivityPage(1); setActivity(null); await loadActivity(member, 1); };
  const changeActivityPage = (requestedPage: number) => { if (!selected || requestedPage < 1) return; setActivityPage(requestedPage); loadActivity(selected, requestedPage); };
  const setActive = async () => { if (!selected || !confirm) return; const active = confirm === "unblock"; try { await adminFetch(`/admin/members/${encodeURIComponent(selected.username)}/${active ? "unblock" : "block"}`, { method: "POST" }); onNotice(`Member ${active ? "reactivated" : "deactivated"}.`); setSelected({ ...selected, active }); setConfirm(null); await query.refetch(); } catch (error) { onNotice((error as Error).message); } };
  const toggleSort = (field: string) => { setPage(1); if (sort === field) setDirection((value) => value === "asc" ? "desc" : "asc"); else { setSort(field); setDirection("asc"); } };
  return <section className="content-stack"><div className="page-intro"><div><p className="eyebrow">Protected member management</p><h2>All Members</h2><p>Server-side search, filtering, sorting, pagination, and protected member detail. Private message bodies are intentionally not rendered.</p></div><Button variant="outline" onClick={() => query.refetch()}><RefreshCw size={16} />Refresh</Button></div><div className="filter-bar"><div className="search-field"><Search size={16} /><Input value={search} onChange={(event) => { setSearch(event.target.value); setPage(1); }} placeholder="Search name, username, role, or title" aria-label="Search members" /></div><select aria-label="Member status" value={status} onChange={(event) => { setStatus(event.target.value); setPage(1); }}><option value="">All statuses</option><option value="active">Active</option><option value="inactive">Inactive</option></select><select aria-label="Member role" value={role} onChange={(event) => { setRole(event.target.value); setPage(1); }}><option value="">All roles</option><option value="member">Member</option><option value="contributor">Contributor</option><option value="creator">Creator</option><option value="admin">Admin</option><option value="owner">Owner</option></select></div><div className="member-layout"><Card><CardHeader><CardTitle>Member directory</CardTitle><CardDescription>{result.total ?? 0} total accounts · page {page}</CardDescription></CardHeader><CardContent><Table><TableHeader><TableRow><TableHead><button className="table-sort" onClick={() => toggleSort("name")}>Account {sort === "name" ? (direction === "asc" ? "↑" : "↓") : ""}</button></TableHead><TableHead><button className="table-sort" onClick={() => toggleSort("role")}>Role</button></TableHead><TableHead>Status</TableHead><TableHead><button className="table-sort" onClick={() => toggleSort("activity")}>Activity</button></TableHead></TableRow></TableHeader><TableBody>{query.isLoading ? <TableRow><TableCell colSpan={4}><LoadingState label="Loading protected member records…" /></TableCell></TableRow> : query.isError ? <TableRow><TableCell colSpan={4}><ErrorState label={query.error?.message || "Member records could not be loaded."} /></TableCell></TableRow> : members.length ? members.map((member) => <TableRow key={member.username} className={selected?.username === member.username ? "row-selected" : ""} onClick={() => openMember(member)}><TableCell><strong>{member.displayName || member.username}</strong><span className="table-subtext">@{member.username}{member.title ? ` · ${member.title}` : ""}</span></TableCell><TableCell><Badge variant="outline">{member.role}</Badge></TableCell><TableCell><Badge variant={member.active ? "success" : "warning"}>{member.active ? "Active" : "Inactive"}</Badge></TableCell><TableCell>{member.topicCount + member.postCount}</TableCell></TableRow>) : <TableRow><TableCell colSpan={4}><EmptyState label="No members matched these filters." /></TableCell></TableRow>}</TableBody></Table><div className="pagination"><span className="muted">Page {page} of {Math.max(1, result.total ? Math.ceil(result.total / 25) : 1)}</span><div><Button size="sm" variant="outline" disabled={page <= 1} onClick={() => setPage((value) => value - 1)}>Previous</Button><Button size="sm" variant="outline" disabled={!result.total || page >= Math.ceil(result.total / 25)} onClick={() => setPage((value) => value + 1)}>Next</Button></div></div></CardContent></Card><MemberDetail selected={selected} activity={activity} loading={loadingDetail} onConfirm={(action) => setConfirm(action)} onActivityPageChange={changeActivityPage} /></div>{confirm && <ConfirmDialog title={`${confirm === "block" ? "Deactivate" : "Reactivate"} member?`} message={confirm === "block" ? "This uses the existing protected block endpoint and will be recorded in the admin audit log." : "This will reactivate the member through the existing protected endpoint."} confirmLabel={confirm === "block" ? "Deactivate" : "Reactivate"} destructive={confirm === "block"} onCancel={() => setConfirm(null)} onConfirm={setActive} />}</section>;
}

function MemberDetailLegacy({ selected, activity, loading, onConfirm }: { selected: Member | null; activity: MemberActivity | null; loading: boolean; onConfirm: (action: "block" | "unblock") => void }) { const [tab, setTab] = useState("overview"); useEffect(() => setTab("overview"), [selected?.username]); if (!selected) return <Card className="member-detail"><CardHeader><CardTitle>Member detail</CardTitle><CardDescription>Select an account to inspect protected activity.</CardDescription></CardHeader><CardContent><EmptyState label="Choose a member from the directory." icon={<Users size={28} />} /></CardContent></Card>; return <Card className="member-detail"><CardHeader><CardTitle>{selected.displayName || selected.username}</CardTitle><CardDescription>@{selected.username} · role {selected.role}</CardDescription></CardHeader><CardContent>{loading ? <LoadingState label="Loading protected activity…" /> : activity ? <div className="detail-stack"><div className="detail-actions"><Badge variant={selected.active ? "success" : "warning"}>{selected.active ? "Active" : "Inactive"}</Badge><Button size="sm" variant={selected.active ? "destructive" : "secondary"} onClick={() => onConfirm(selected.active ? "block" : "unblock")}>{selected.active ? "Deactivate" : "Reactivate"}</Button></div><div className="detail-tabs" role="tablist">{["overview", "profile", "posts", "comments", "videos", "articles", "account"].map((name) => <button key={name} role="tab" aria-selected={tab === name} className={tab === name ? "is-active" : ""} onClick={() => setTab(name)}>{name}</button>)}</div>{tab === "overview" && <div className="detail-facts"><span><strong>Joined</strong>{new Date(activity.member.createdAt).toLocaleDateString()}</span><span><strong>Posts</strong>{activity.posts.length}</span><span><strong>Comments</strong>{activity.comments.length}</span><span><strong>TPI videos</strong>{activity.tpiVideos.length}</span></div>}{tab === "profile" && <div className="detail-facts"><span><strong>Display name</strong>{activity.member.displayName || "—"}</span><span><strong>Title</strong>{activity.member.title || "—"}</span><span><strong>Role</strong>{activity.member.role}</span><span><strong>State</strong>{selected.active ? "Active" : "Inactive"}</span></div>}{tab === "posts" && <ActivityList rows={activity.posts.map((post) => ({ id: post.id, label: post.body, status: post.status, createdAt: post.createdAt }))} empty="No Community Feed posts returned." />}{tab === "comments" && <ActivityList rows={activity.comments.map((comment) => ({ id: comment.id, label: comment.body || comment.text || "Comment", status: comment.status, createdAt: comment.createdAt }))} empty="No comments returned." />}{tab === "videos" && <ActivityList rows={activity.tpiVideos.map((video) => ({ id: video.id, label: video.title, status: video.status, createdAt: video.createdAt }))} empty="No TPI Videos returned." />}{tab === "articles" && <ActivityList rows={activity.articles.map((article) => ({ id: article.id, label: article.title, status: article.status, createdAt: article.createdAt }))} empty="No articles returned." />}{tab === "account" && <div className="notice-panel"><Badge variant="warning">Protected</Badge><p>Role, access, and notification mutations remain on existing protected contracts. No private messenger conversation data is exposed in this preview.</p></div>}</div> : <ErrorState label="No activity response was returned." />}</CardContent></Card>; }

function MemberDetail({ selected, activity, loading, onConfirm, onActivityPageChange }: { selected: Member | null; activity: MemberActivity | null; loading: boolean; onConfirm: (action: "block" | "unblock") => void; onActivityPageChange: (page: number) => void }) {
  const [tab, setTab] = useState("overview");
  useEffect(() => setTab("overview"), [selected?.username]);
  if (!selected) return <Card className="member-detail"><CardHeader><CardTitle>Member detail</CardTitle><CardDescription>Select an account to inspect protected activity.</CardDescription></CardHeader><CardContent><EmptyState label="Choose a member from the directory." icon={<Users size={28} />} /></CardContent></Card>;
  if (loading) return <Card className="member-detail"><CardHeader><CardTitle>{selected.displayName || selected.username}</CardTitle></CardHeader><CardContent><LoadingState label="Loading protected activity…" /></CardContent></Card>;
  if (!activity) return <Card className="member-detail"><CardHeader><CardTitle>{selected.displayName || selected.username}</CardTitle></CardHeader><CardContent><ErrorState label="No activity response was returned." /></CardContent></Card>;
  const tabs = ["overview", "profile", "posts", "comments", "reactions", "videos", "reports", "moderation", "account"];
  const page = activity.activityPagination?.page || 1;
  const canNext = Object.values(activity.activityPagination?.hasMore || {}).some(Boolean);
  return <Card className="member-detail"><CardHeader><CardTitle>{selected.displayName || selected.username}</CardTitle><CardDescription>@{selected.username} · role {selected.role}</CardDescription></CardHeader><CardContent><div className="detail-stack"><div className="detail-actions"><Badge variant={selected.active ? "success" : "warning"}>{selected.active ? "Active" : "Inactive"}</Badge><Button size="sm" variant={selected.active ? "destructive" : "secondary"} onClick={() => onConfirm(selected.active ? "block" : "unblock")}>{selected.active ? "Deactivate" : "Reactivate"}</Button></div><div className="detail-tabs" role="tablist">{tabs.map((name) => <button key={name} role="tab" aria-selected={tab === name} className={tab === name ? "is-active" : ""} onClick={() => setTab(name)}>{name === "moderation" ? "Moderation History" : name === "account" ? "Account Management" : name}</button>)}</div>{tab === "overview" && <div className="detail-facts"><span><strong>Joined</strong>{new Date(activity.member.createdAt).toLocaleDateString()}</span><span><strong>Posts</strong>{activity.posts.length}</span><span><strong>Comments</strong>{activity.comments.length}</span><span><strong>Reactions</strong>{activity.reactionActivity.length}</span><span><strong>Videos</strong>{activity.tpiVideos.length}</span><span><strong>Reports</strong>{activity.reports.length}</span></div>}{tab === "profile" && <div className="detail-facts"><span><strong>Display name</strong>{activity.member.displayName || "—"}</span><span><strong>Title</strong>{activity.member.title || "—"}</span><span><strong>Role</strong>{activity.member.role}</span><span><strong>State</strong>{selected.active ? "Active" : "Inactive"}</span></div>}{tab === "posts" && <ActivityList rows={activity.posts.map((post) => ({ id: post.id, label: post.body, status: post.status, createdAt: post.createdAt, href: `/member-home.html?member=1#post-${encodeURIComponent(post.id)}` }))} empty="No Community Feed posts returned." />}{tab === "comments" && <ActivityList rows={activity.comments.map((comment) => ({ id: comment.id, label: comment.body || comment.text || "Comment", status: comment.status, createdAt: comment.createdAt }))} empty="No comments returned." />}{tab === "reactions" && <ActivityList rows={activity.reactionActivity.map((reaction) => ({ id: reaction.id, label: `${reaction.reaction} · ${reaction.label || reaction.targetId}`, status: reaction.targetType, createdAt: reaction.createdAt, href: reaction.contentHref }))} empty="No reactions returned." />}{tab === "videos" && <ActivityList rows={activity.tpiVideos.map((video) => ({ id: video.id, label: video.title, status: video.status, createdAt: video.createdAt, href: `/tpi-video.html?id=${encodeURIComponent(video.id)}` }))} empty="No TPI Videos returned." />}{tab === "reports" && <ReportList reports={activity.reports} />}{tab === "moderation" && <ModerationList rows={activity.moderationHistory} />}{tab === "account" && <div className="notice-panel"><Badge variant="warning">Protected</Badge><p>Account status changes use existing server-side authorization and audit logging. Private conversation content is not included in this member record; messenger evidence remains report-scoped.</p></div>}<div className="activity-page-note"><span className="muted">Activity page {page} · 25 per request</span><div><Button size="sm" variant="outline" disabled={page <= 1 || loading} onClick={() => onActivityPageChange(page - 1)}>Previous</Button><Button size="sm" variant="outline" disabled={!canNext || loading} onClick={() => onActivityPageChange(page + 1)}>Next</Button></div></div></div></CardContent></Card>;
}

function ReportList({ reports }: { reports: MemberActivity["reports"] }) { return reports.length ? <div className="moderation-list">{reports.map((report) => <div className="moderation-row" key={`${report.reportType}-${report.id}`}><div><strong>{report.reportType} report · {report.memberRelation || "related"}</strong><p>{report.reason}{report.description ? ` — ${report.description}` : ""}</p><span className="table-subtext">{report.contentLabel || report.contentId || report.contentType || "Private evidence"} · {new Date(report.createdAt).toLocaleString()}</span></div><Badge variant={report.status === "open" || report.status === "pending" ? "warning" : "success"}>{report.status}</Badge></div>)}</div> : <EmptyState label="No reports involving this member were returned." />; }
function ModerationList({ rows }: { rows: MemberActivity["moderationHistory"] }) { return rows.length ? <div>{rows.map((row) => <div className="activity-item" key={row.id}><Badge variant="outline">{row.action}</Badge><span>{row.actorUsername} · {row.actorRole}<small>{row.targetType || "member"} · {new Date(row.createdAt).toLocaleString()}</small></span></div>)}</div> : <EmptyState label="No moderation history returned for this member." />; }

function CommunityPosts({ onNotice }: { onNotice: (value: string) => void }) { const [posts, setPosts] = useState<CommunityPost[]>([]); const [search, setSearch] = useState(""); const [status, setStatus] = useState("active"); const [loading, setLoading] = useState(true); const [page, setPage] = useState(1); const [total, setTotal] = useState(0); const load = () => { setLoading(true); const params = new URLSearchParams({ page: String(page), pageSize: "25", status }); if (search) params.set("search", search); adminFetch<{ posts: CommunityPost[]; pagination?: { total?: number } }>(`/admin/community/posts?${params}`).then((body) => { setPosts(body.posts || []); setTotal(body.pagination?.total || 0); }).catch((error) => onNotice(error.message)).finally(() => setLoading(false)); }; useEffect(load, [page, status]); return <section className="content-stack"><div className="page-intro"><div><p className="eyebrow">Community Feed</p><h2>Posts &amp; moderation</h2><p>Review active status and engagement from the existing Community Feed contract. Deleted records are preserved and available only through the explicit Deleted filter.</p></div><Button variant="outline" onClick={load}><RefreshCw size={16} />Refresh</Button></div><Card><CardHeader><div className="filter-bar"><div className="search-field"><Search size={16} /><Input value={search} onChange={(event) => setSearch(event.target.value)} onKeyDown={(event) => event.key === "Enter" && (setPage(1), load())} placeholder="Search posts or authors" aria-label="Search community posts" /></div><select aria-label="Post status" value={status} onChange={(event) => { setStatus(event.target.value); setPage(1); }}><option value="active">Active (not deleted)</option><option value="visible">Visible</option><option value="hidden">Hidden</option><option value="deleted">Deleted</option></select></div></CardHeader><CardContent><Table><TableHeader><TableRow><TableHead>Post</TableHead><TableHead>Author</TableHead><TableHead>Status</TableHead><TableHead>Engagement</TableHead><TableHead>Created</TableHead></TableRow></TableHeader><TableBody>{loading ? <TableRow><TableCell colSpan={5}><LoadingState label="Loading Community Feed records…" /></TableCell></TableRow> : posts.length ? posts.map((post) => <CommunityPostRow key={post.id} post={post} onNotice={onNotice} onReload={load} />) : <TableRow><TableCell colSpan={5}><EmptyState label="No posts matched this filter." /></TableCell></TableRow>}</TableBody></Table><div className="pagination"><span className="muted">{total} matching posts</span><div><Button size="sm" variant="outline" disabled={page <= 1} onClick={() => setPage((value) => value - 1)}>Previous</Button><Button size="sm" variant="outline" disabled={page >= Math.ceil(total / 25)} onClick={() => setPage((value) => value + 1)}>Next</Button></div></div></CardContent></Card><CommunityComments onNotice={onNotice} /></section>; }
function CommunityPostRow({ post, onNotice, onReload }: { post: CommunityPost; onNotice: (value: string) => void; onReload: () => void }) { const [busy, setBusy] = useState(false); const update = async (status: string) => { setBusy(true); try { await adminFetch(`/admin/community/posts/${encodeURIComponent(post.id)}/status`, { method: "POST", body: JSON.stringify({ status }) }); onNotice(`Post status changed to ${status}.`); onReload(); } catch (error) { onNotice((error as Error).message); } finally { setBusy(false); } }; return <TableRow><TableCell><strong>{post.title || "Untitled post"}</strong><span className="table-subtext">{post.preview || "No preview text"}</span></TableCell><TableCell>{post.authorDisplayName || post.authorUsername || "Unknown"}</TableCell><TableCell><Badge variant={post.status === "visible" ? "success" : "warning"}>{post.status}</Badge></TableCell><TableCell>{post.commentCount} comments · {post.reactionCount} reactions</TableCell><TableCell><span className="table-subtext">{new Date(post.createdAt).toLocaleDateString()}</span><select className="inline-action" disabled={busy} aria-label={`Change status for ${post.title || post.id}`} value={post.status} onChange={(event) => update(event.target.value)}><option value="visible">Visible</option><option value="hidden">Hidden</option><option value="deleted">Deleted</option></select></TableCell></TableRow>; }

function CommunityComments({ onNotice }: { onNotice: (value: string) => void }) {
  const [comments, setComments] = useState<AdminCommunityComment[]>([]);
  const [status, setStatus] = useState("visible");
  const [search, setSearch] = useState("");
  const [page, setPage] = useState(1);
  const [total, setTotal] = useState(0);
  const [loading, setLoading] = useState(true);
  const load = () => {
    setLoading(true);
    const params = new URLSearchParams({ page: String(page), pageSize: "25", status });
    if (search) params.set("search", search);
    adminFetch<{ comments: AdminCommunityComment[]; pagination?: { total?: number } }>(`/admin/community/comments?${params}`).then((body) => {
      setComments(body.comments || []);
      setTotal(body.pagination?.total || 0);
    }).catch((error) => onNotice(error.message)).finally(() => setLoading(false));
  };
  useEffect(load, [page, status]);
  return <Card><CardHeader><div className="filter-bar"><div className="search-field"><Search size={16} /><Input value={search} onChange={(event) => setSearch(event.target.value)} onKeyDown={(event) => event.key === "Enter" && (setPage(1), load())} placeholder="Search comments, posts, or authors" aria-label="Search community comments" /></div><select aria-label="Community comment status" value={status} onChange={(event) => { setStatus(event.target.value); setPage(1); }}><option value="visible">Visible</option><option value="deleted">Deleted</option><option value="all">All</option></select><Badge variant="outline">Metadata only</Badge><Button variant="outline" onClick={load}><RefreshCw size={16} />Refresh</Button></div><CardTitle>Community Comments</CardTitle><CardDescription>Read-only moderation context for Community Feed comments. No comment mutation is exposed until a verified administrative contract exists.</CardDescription></CardHeader><CardContent><Table><TableHeader><TableRow><TableHead>Comment</TableHead><TableHead>Author</TableHead><TableHead>Post</TableHead><TableHead>Status</TableHead><TableHead>Created</TableHead></TableRow></TableHeader><TableBody>{loading ? <TableRow><TableCell colSpan={5}><LoadingState label="Loading Community comments…" /></TableCell></TableRow> : comments.length ? comments.map((comment) => <TableRow key={comment.id}><TableCell><span>{comment.preview || "No comment preview returned."}</span><span className="table-subtext">{comment.id}</span></TableCell><TableCell>{comment.authorDisplayName || comment.authorUsername || "Unknown"}</TableCell><TableCell>{comment.postTitle || comment.postId}</TableCell><TableCell><Badge variant={comment.status === "visible" ? "success" : "warning"}>{comment.status}</Badge></TableCell><TableCell>{comment.createdAt ? new Date(comment.createdAt).toLocaleString() : "—"}</TableCell></TableRow>) : <TableRow><TableCell colSpan={5}><EmptyState label="No Community comments matched this filter." /></TableCell></TableRow>}</TableBody></Table><div className="pagination"><span className="muted">{total} matching comments</span><div><Button size="sm" variant="outline" disabled={page <= 1} onClick={() => setPage((value) => value - 1)}>Previous</Button><Button size="sm" variant="outline" disabled={page >= Math.ceil(total / 25)} onClick={() => setPage((value) => value + 1)}>Next</Button></div></div></CardContent></Card>;
}

function Comments({ onNotice }: { onNotice: (value: string) => void }) { const [status, setStatus] = useState("pending"); const [comments, setComments] = useState<ClassicComment[]>([]); const [page, setPage] = useState(1); const [total, setTotal] = useState(0); const [loading, setLoading] = useState(true); const load = () => { setLoading(true); adminFetch<{ comments: ClassicComment[]; pagination?: { total?: number } }>(`/admin/comments?status=${status}&page=${page}&pageSize=50`).then((body) => { setComments(body.comments || []); setTotal(body.pagination?.total || 0); }).catch((error) => onNotice(error.message)).finally(() => setLoading(false)); }; useEffect(load, [status, page]); const action = async (comment: ClassicComment, method: "approve" | "delete") => { try { await adminFetch(`/admin/comments/${encodeURIComponent(comment.id)}${method === "approve" ? "/approve" : ""}`, { method: method === "approve" ? "POST" : "DELETE" }); onNotice(`Comment ${method === "approve" ? "approved" : "deleted"}.`); load(); } catch (error) { onNotice((error as Error).message); } }; return <section className="content-stack"><div className="page-intro"><div><p className="eyebrow">Education Center</p><h2>Article Comment Moderation</h2><p>Review classic article comments here. Community Feed comments remain in the Community moderation resources.</p></div><Button variant="outline" onClick={load}><RefreshCw size={16} />Refresh</Button></div><Card><CardHeader><div className="filter-bar"><select aria-label="Comment status" value={status} onChange={(event) => { setStatus(event.target.value); setPage(1); }}><option value="pending">Pending</option><option value="approved">Approved</option></select><Badge variant="outline">Classic article comments</Badge></div><CardDescription>{total} matching comments · page {page}</CardDescription></CardHeader><CardContent>{loading ? <LoadingState label="Loading article comments…" /> : comments.length ? <div className="moderation-list">{comments.map((comment) => <div className="moderation-row" key={comment.id}><div><strong>{comment.name || comment.authorUsername || "Commenter"}</strong><p>{comment.text || "No comment text returned."}</p><span className="table-subtext">{comment.pageId || "Unknown page"} · {new Date(comment.createdAt).toLocaleString()}</span></div><div className="detail-actions"><Badge variant={comment.status === "approved" ? "success" : "warning"}>{comment.status}</Badge>{comment.status === "pending" && <Button size="sm" onClick={() => action(comment, "approve")}>Approve</Button>}<Button size="sm" variant="destructive" onClick={() => action(comment, "delete")}>Delete</Button></div></div>)}</div> : <EmptyState label={`No ${status} article comments returned.`} />}<div className="pagination"><span className="muted">Page {page} · 50 per request</span><div><Button size="sm" variant="outline" disabled={page <= 1} onClick={() => setPage((value) => value - 1)}>Previous</Button><Button size="sm" variant="outline" disabled={!total || page >= Math.ceil(total / 50)} onClick={() => setPage((value) => value + 1)}>Next</Button></div></div></CardContent></Card></section>; }

function Audit({ onNotice, historyOnly }: { onNotice: (value: string) => void; historyOnly?: boolean }) {
  type AuditRow = { id: string; actorUsername: string; actorRole: string; action: string; targetType?: string; targetId?: string; createdAt: string };
  const [logs, setLogs] = useState<AuditRow[]>([]);
  const [loading, setLoading] = useState(true);
  const [query, setQuery] = useState("");
  const [page, setPage] = useState(1);
  const [total, setTotal] = useState(0);
  const load = () => {
    setLoading(true);
    const params = new URLSearchParams({ page: String(page), limit: "50" });
    if (query.trim()) params.set("q", query.trim());
    adminFetch<{ logs: AuditRow[]; pagination?: { total?: number } }>(`/admin/audit-logs?${params}`).then((body) => {
      setLogs(body.logs || []);
      setTotal(body.pagination?.total || 0);
    }).catch((error) => onNotice(error.message)).finally(() => setLoading(false));
  };
  useEffect(load, [page]);
  const rows = historyOnly ? logs.filter((log) => /moderat|comment|community|block|deactivat|report/i.test(`${log.action} ${log.targetType || ""}`)) : logs;
  return <section className="content-stack"><div className="page-intro"><div><p className="eyebrow">Accountability</p><h2>{historyOnly ? "Moderation History" : "Audit Logs"}</h2><p>Administrative actions are shown without message bodies, recordings, stream keys, or private conversation content.</p></div><Button variant="outline" onClick={load}><RefreshCw size={16} />Refresh</Button></div><Card><CardHeader><div className="filter-bar"><div className="search-field"><Search size={16} /><Input value={query} onChange={(event) => setQuery(event.target.value)} onKeyDown={(event) => { if (event.key === "Enter") { setPage(1); if (page === 1) load(); } }} placeholder="Actor, action, or target" aria-label="Filter audit logs" /></div><Badge variant="outline">Protected read-only</Badge></div></CardHeader><CardContent className="audit-list">{loading ? <LoadingState label="Loading audit history…" /> : rows.length ? rows.map((log) => <div className="audit-row" key={log.id}><div><strong>{log.action}</strong><span>{log.targetType || "system"}{log.targetId ? ` · ${log.targetId}` : ""}</span></div><div><Badge variant="outline">{log.actorUsername} · {log.actorRole}</Badge><time>{new Date(log.createdAt).toLocaleString()}</time></div></div>) : <EmptyState label="No audit records matched this filter." icon={<Activity size={28} />} />}<div className="pagination"><span className="muted">{total} matching audit records</span><div><Button size="sm" variant="outline" disabled={page <= 1} onClick={() => setPage((value) => value - 1)}>Previous</Button><Button size="sm" variant="outline" disabled={page >= Math.ceil(total / 50)} onClick={() => setPage((value) => value + 1)}>Next</Button></div></div></CardContent></Card></section>;
}

function Contributors({ onNotice }: { onNotice: (value: string) => void }) {
  const [contributors, setContributors] = useState<AdminContributor[]>([]);
  const [invites, setInvites] = useState<AdminInvite[]>([]);
  const [search, setSearch] = useState("");
  const [query, setQuery] = useState("");
  const [status, setStatus] = useState("active");
  const [page, setPage] = useState(1);
  const [total, setTotal] = useState(0);
  const [invitePage, setInvitePage] = useState(1);
  const [inviteTotal, setInviteTotal] = useState(0);
  const [loading, setLoading] = useState(true);
  const [inviteType, setInviteType] = useState("standard");
  const [inviteRole, setInviteRole] = useState("contributor");
  const [inviteCode, setInviteCode] = useState("");
  const [creatingInvite, setCreatingInvite] = useState(false);
  const load = () => {
    setLoading(true);
    const params = new URLSearchParams({ status, page: String(page), pageSize: "50" });
    if (query.trim()) params.set("search", query.trim());
    Promise.all([
      adminFetch<{ contributors: AdminContributor[]; pagination?: { total?: number } }>("/admin/contributors?" + params.toString()),
      adminFetch<{ invites: AdminInvite[]; pagination?: { total?: number } }>(`/invites?page=${invitePage}&pageSize=25`)
    ]).then(([directory, inviteList]) => {
      setContributors(directory.contributors || []);
      setTotal(directory.pagination?.total || 0);
      setInvites(inviteList.invites || []);
      setInviteTotal(inviteList.pagination?.total || 0);
    }).catch((error) => onNotice(error.message)).finally(() => setLoading(false));
  };
  useEffect(load, [status, page, query, invitePage]);
  const changeInviteType = (value: string) => {
    setInviteType(value);
    setInviteRole(value === "D" ? "owner" : value === "AD" ? "admin" : "contributor");
  };
  const createInvite = async (event: FormEvent) => {
    event.preventDefault();
    setCreatingInvite(true);
    try {
      const suppliedCode = inviteCode.trim();
      const generatedCode = suppliedCode || (inviteType === "standard" ? "" : inviteType + "-" + Math.random().toString(36).slice(2, 8).toUpperCase());
      await adminFetch<{ invite: AdminInvite }>("/invites", { method: "POST", body: JSON.stringify({ code: generatedCode, role: inviteRole }) });
      onNotice("Invite created through the existing protected invitation contract.");
      setInviteCode("");
      load();
    } catch (error) {
      onNotice((error as Error).message);
    } finally {
      setCreatingInvite(false);
    }
  };
  return <section className="content-stack">
    <div className="page-intro"><div><p className="eyebrow">Content &amp; Publishing</p><h2>Contributor Management</h2><p>Manage the protected contributor directory, invitation types, and access levels through the existing server-side contracts. Invite codes are only returned to authorized administrators.</p></div><Button variant="outline" onClick={load}><RefreshCw size={16} />Refresh</Button></div>
    <div className="two-column">
      <Card>
        <CardHeader><CardTitle>Contributor Directory</CardTitle><CardDescription>Active and inactive accounts with protected role/title controls.</CardDescription></CardHeader>
        <CardContent>
          <div className="filter-bar"><div className="search-field"><Search size={16} /><Input value={search} onChange={(event) => setSearch(event.target.value)} onKeyDown={(event) => { if (event.key === "Enter") { setQuery(search); setPage(1); } }} placeholder="Search name, username, title, or role" aria-label="Search contributors" /></div><select aria-label="Contributor status" value={status} onChange={(event) => { setStatus(event.target.value); setPage(1); }}><option value="active">Active</option><option value="inactive">Inactive</option><option value="all">All accounts</option></select></div>
          <Table><TableHeader><TableRow><TableHead>Contributor</TableHead><TableHead>Role</TableHead><TableHead>State</TableHead><TableHead>Access controls</TableHead></TableRow></TableHeader><TableBody>
            {loading ? <TableRow><TableCell colSpan={4}><LoadingState label="Loading contributor directory…" /></TableCell></TableRow> : contributors.length ? contributors.map((contributor) => <ContributorRow key={contributor.username} contributor={contributor} onNotice={onNotice} onReload={load} />) : <TableRow><TableCell colSpan={4}><EmptyState label="No contributor accounts matched this filter." /></TableCell></TableRow>}
          </TableBody></Table>
          <div className="pagination"><span className="muted">{total} matching contributors · page {page}</span><div><Button size="sm" variant="outline" disabled={page <= 1} onClick={() => setPage((value) => value - 1)}>Previous</Button><Button size="sm" variant="outline" disabled={!total || page >= Math.ceil(total / 50)} onClick={() => setPage((value) => value + 1)}>Next</Button></div></div>
        </CardContent>
      </Card>
      <Card>
        <CardHeader><CardTitle>Contributor Invites</CardTitle><CardDescription>Generate the existing invitation types without changing validation or expiration behavior.</CardDescription></CardHeader>
        <CardContent>
          <form className="detail-stack" onSubmit={createInvite}><label><span>Invite type</span><select value={inviteType} onChange={(event) => changeInviteType(event.target.value)}><option value="standard">Standard Contributor</option><option value="D">Director</option><option value="AD">Assistant Director</option><option value="ABM">Advisory Board Member</option></select></label><label><span>Access level</span><select value={inviteRole} onChange={(event) => setInviteRole(event.target.value)}><option value="contributor">Contributor</option><option value="admin">Admin</option><option value="owner">Owner</option></select></label><label><span>Invite code (optional)</span><Input value={inviteCode} onChange={(event) => setInviteCode(event.target.value)} placeholder="Leave blank to generate" /></label><Button type="submit" disabled={creatingInvite}>{creatingInvite ? "Creating…" : "Generate Invite Link"}</Button></form>
          <div className="notice-panel"><Badge variant="outline">Protected</Badge><p>Director and Admin invite permissions remain enforced by the server. Existing invite assignment and validation rules are unchanged.</p></div>
          <div className="invite-list"><h3>Existing invites</h3>{invites.length ? invites.map((invite) => <div className="activity-item" key={invite.code + "-" + invite.createdAt}><code>{invite.code}</code><Badge variant={Boolean(invite.used) ? "outline" : "success"}>{Boolean(invite.used) ? "Used" : "Available"}</Badge><span>{invite.role}<small>{invite.createdAt ? new Date(invite.createdAt).toLocaleString() : "—"}{invite.usedBy ? " · used by " + invite.usedBy : ""}</small></span></div>) : <EmptyState label="No invitation records returned." />}</div><div className="pagination"><span className="muted">{inviteTotal} matching invites · page {invitePage}</span><div><Button size="sm" variant="outline" disabled={invitePage <= 1} onClick={() => setInvitePage((value) => value - 1)}>Previous</Button><Button size="sm" variant="outline" disabled={!inviteTotal || invitePage >= Math.ceil(inviteTotal / 25)} onClick={() => setInvitePage((value) => value + 1)}>Next</Button></div></div>
        </CardContent>
      </Card>
    </div>
  </section>;
}
function ContributorRow({ contributor, onNotice, onReload }: { contributor: AdminContributor; onNotice: (value: string) => void; onReload: () => void }) {
  const [title, setTitle] = useState(contributor.title || "");
  const [role, setRole] = useState(contributor.role);
  const [busy, setBusy] = useState(false);
  const save = async () => {
    setBusy(true);
    try {
      await adminFetch<{ contributor: AdminContributor }>("/admin/contributors/title", { method: "POST", body: JSON.stringify({ username: contributor.username, title, role }) });
      onNotice(`Updated ${contributor.displayName || contributor.username}.`);
      onReload();
    } catch (error) {
      onNotice((error as Error).message);
    } finally {
      setBusy(false);
    }
  };
  return <TableRow><TableCell><strong>{contributor.displayName || contributor.username}</strong><span className="table-subtext">@{contributor.username}{contributor.organization ? ` · ${contributor.organization}` : ""}</span></TableCell><TableCell><select className="inline-action" value={role} onChange={(event) => setRole(event.target.value)} aria-label={`Role for ${contributor.username}`}><option value="member">Member</option><option value="contributor">Contributor</option><option value="admin">Admin</option><option value="owner">Owner</option></select><Input value={title} onChange={(event) => setTitle(event.target.value)} aria-label={`Title for ${contributor.username}`} placeholder="Title" /></TableCell><TableCell><Badge variant={contributor.active ? "success" : "warning"}>{contributor.active ? "Active" : "Inactive"}</Badge><span className="table-subtext">Joined {contributor.createdAt ? new Date(contributor.createdAt).toLocaleDateString() : "—"}</span></TableCell><TableCell><Button size="sm" disabled={busy || !contributor.active} onClick={save}>{busy ? "Saving…" : "Save access"}</Button></TableCell></TableRow>;
}

function Teams({ onNotice }: { onNotice: (value: string) => void }) {
  const [status, setStatus] = useState<AdminTeam["status"]>("pending");
  const [teams, setTeams] = useState<AdminTeam[]>([]);
  const [search, setSearch] = useState("");
  const [query, setQuery] = useState("");
  const [page, setPage] = useState(1);
  const [total, setTotal] = useState(0);
  const [loading, setLoading] = useState(true);
  const [busyId, setBusyId] = useState<string | null>(null);
  const load = () => {
    setLoading(true);
    const params = new URLSearchParams({ status, page: String(page), pageSize: "50" });
    if (query.trim()) params.set("search", query.trim());
    adminFetch<{ teams: AdminTeam[]; pagination?: { total?: number } }>(`/admin/teams?${params}`).then((body) => {
      setTeams(body.teams || []);
      setTotal(body.pagination?.total || 0);
    }).catch((error) => onNotice(error.message)).finally(() => setLoading(false));
  };
  useEffect(load, [status, page, query]);
  const updateStatus = async (team: AdminTeam, nextStatus: "approved" | "rejected") => {
    setBusyId(team.id);
    try {
      await adminFetch("/admin/teams/" + encodeURIComponent(team.id) + "/status", { method: "POST", body: JSON.stringify({ status: nextStatus }) });
      onNotice("Team " + (nextStatus === "approved" ? "approved" : "rejected") + ".");
      load();
    } catch (error) {
      onNotice((error as Error).message);
    } finally {
      setBusyId(null);
    }
  };
  return <section className="content-stack">
    <div className="page-intro">
      <div><p className="eyebrow">Content &amp; Publishing</p><h2>Paranormal Teams</h2><p>Review registered team submissions through the existing protected approval contract. Imported directory records remain subject to the existing publication policy.</p></div>
      <Button variant="outline" onClick={load}><RefreshCw size={16} />Refresh</Button>
    </div>
    <Card>
      <CardHeader>
        <div className="filter-bar">
          <div className="search-field"><Search size={16} /><Input value={search} onChange={(event) => setSearch(event.target.value)} onKeyDown={(event) => { if (event.key === "Enter") { setQuery(search); setPage(1); } }} placeholder="Search team, location, or submitter" aria-label="Search Paranormal Teams" /></div>
          <select aria-label="Team status" value={status} onChange={(event) => { setStatus(event.target.value as AdminTeam["status"]); setPage(1); }}>
            <option value="pending">Pending approvals</option><option value="approved">Approved teams</option><option value="rejected">Rejected teams</option>
          </select>
        </div>
        <CardDescription>{total} matching teams · page {page}</CardDescription>
      </CardHeader>
      <CardContent>
        <Table>
          <TableHeader><TableRow><TableHead>Team</TableHead><TableHead>Location</TableHead><TableHead>Record</TableHead><TableHead>Status</TableHead><TableHead>Submitted</TableHead><TableHead>Actions</TableHead></TableRow></TableHeader>
          <TableBody>
            {loading ? <TableRow><TableCell colSpan={6}><LoadingState label="Loading Paranormal Teams…" /></TableCell></TableRow> : teams.length ? teams.map((team) => <TableRow key={team.id}>
              <TableCell><strong>{team.name}</strong><span className="table-subtext">{team.acronym || "No acronym"}{team.submitterName ? " · submitted by " + team.submitterName : ""}</span></TableCell>
              <TableCell>{[team.city, team.state, team.country].filter(Boolean).join(", ") || "—"}</TableCell>
              <TableCell><Badge variant={team.recordType === "REGISTERED_TEAM" ? "outline" : "warning"}>{team.recordType || "Unknown"}</Badge>{team.externalSource && <span className="table-subtext">{team.externalSource}</span>}</TableCell>
              <TableCell><Badge variant={team.status === "approved" ? "success" : team.status === "pending" ? "warning" : "outline"}>{team.status}</Badge></TableCell>
              <TableCell><span className="table-subtext">{team.createdAt ? new Date(team.createdAt).toLocaleDateString() : "—"}</span></TableCell>
              <TableCell>{team.status === "pending" ? <div className="detail-actions"><Button size="sm" disabled={busyId === team.id} onClick={() => updateStatus(team, "approved")}>Approve</Button><Button size="sm" variant="destructive" disabled={busyId === team.id} onClick={() => updateStatus(team, "rejected")}>Reject</Button></div> : <span className="table-subtext">{team.reviewedBy ? "Reviewed by " + team.reviewedBy : "Previously reviewed"}</span>}</TableCell>
            </TableRow>) : <TableRow><TableCell colSpan={6}><EmptyState label={"No " + status + " Paranormal Teams matched this filter."} /></TableCell></TableRow>}
          </TableBody>
        </Table>
        <div className="pagination"><span className="muted">{total} matching teams</span><div><Button size="sm" variant="outline" disabled={page <= 1} onClick={() => setPage((value) => value - 1)}>Previous</Button><Button size="sm" variant="outline" disabled={!total || page >= Math.ceil(total / 50)} onClick={() => setPage((value) => value + 1)}>Next</Button></div></div>
        <div className="notice-panel"><Badge variant="outline">Server-side authorization preserved</Badge></div>
      </CardContent>
    </Card>
  </section>;
}
function PlatformHealth({ onNotice }: { onNotice: (value: string) => void }) {
  const [runs, setRuns] = useState<AdminScraperRun[]>([]);
  const [providers, setProviders] = useState<AdminProviderStatus[]>([]);
  const [latest, setLatest] = useState<Record<string, AdminScraperRun>>({});
  const [loading, setLoading] = useState(true);
  const load = () => {
    setLoading(true);
    adminFetch<{ runs: AdminScraperRun[]; providers: AdminProviderStatus[]; latest: Record<string, AdminScraperRun> }>("/admin/scraper-runs?limit=50").then((body) => {
      setRuns(body.runs || []);
      setProviders(body.providers || []);
      setLatest(body.latest || {});
    }).catch((error) => onNotice(error.message)).finally(() => setLoading(false));
  };
  useEffect(load, []);
  const latestRows = Object.entries(latest);
  return <section className="content-stack"><div className="page-intro"><div><p className="eyebrow">System</p><h2>Platform Health</h2><p>Read-only scraper and provider health from the existing administrative monitoring contract. Refreshing this view does not start a scraper job.</p></div><Button variant="outline" onClick={load}><RefreshCw size={16} />Refresh</Button></div><div className="two-column"><Card><CardHeader><CardTitle>Video providers</CardTitle><CardDescription>Provider capability states are explicit; not-configured providers are not presented as operational.</CardDescription></CardHeader><CardContent><div className="status-list">{providers.length ? providers.map((provider) => <div key={provider.key}><Badge variant={provider.state === "active" ? "success" : "warning"}>{provider.state}</Badge><span>{provider.label}</span></div>) : <EmptyState label="No provider status returned." />}</div></CardContent></Card><Card><CardHeader><CardTitle>Latest completed runs</CardTitle><CardDescription>{latestRows.length} scraper/provider summaries returned.</CardDescription></CardHeader><CardContent>{loading ? <LoadingState label="Loading platform health…" /> : latestRows.length ? <div className="activity-list">{latestRows.map(([key, run]) => <div className="activity-item" key={key}><Badge variant={run.status === "success" || run.status === "completed" ? "success" : "warning"}>{run.status}</Badge><span>{key}<small>{run.completedAt ? new Date(run.completedAt).toLocaleString() : "No completed timestamp"} · {Number(run.found || 0).toLocaleString()} found · {Number(run.inserted || 0).toLocaleString()} added</small></span></div>)}</div> : <EmptyState label="No completed scraper runs returned." />}</CardContent></Card></div><Card><CardHeader><CardTitle>Recent scraper runs</CardTitle><CardDescription>Sanitized run history; provider error text remains controlled by the existing API.</CardDescription></CardHeader><CardContent><Table><TableHeader><TableRow><TableHead>When</TableHead><TableHead>Scraper</TableHead><TableHead>Source</TableHead><TableHead>Status</TableHead><TableHead>Results</TableHead><TableHead>Duration</TableHead></TableRow></TableHeader><TableBody>{loading ? <TableRow><TableCell colSpan={6}><LoadingState label="Loading scraper history…" /></TableCell></TableRow> : runs.length ? runs.map((run) => <TableRow key={run.id}><TableCell>{run.startedAt ? new Date(run.startedAt).toLocaleString() : "—"}</TableCell><TableCell>{run.scraperType}</TableCell><TableCell>{run.source || "—"}</TableCell><TableCell><Badge variant={run.status === "success" || run.status === "completed" ? "success" : "warning"}>{run.status}</Badge></TableCell><TableCell>{Number(run.found || 0).toLocaleString()} found · {Number(run.inserted || 0).toLocaleString()} added · {Number(run.errorCount || 0).toLocaleString()} errors</TableCell><TableCell>{run.durationMs == null ? "—" : `${Number(run.durationMs).toLocaleString()} ms`}</TableCell></TableRow>) : <TableRow><TableCell colSpan={6}><EmptyState label="No recent scraper runs returned." /></TableCell></TableRow>}</TableBody></Table></CardContent></Card></section>;
}

