function Founding50({ onNotice }: { onNotice: (value: string) => void }) {
  const [summary, setSummary] = useState<{ status?: string; capacity?: number; allocated?: number | null; remaining?: number | null; active?: number; pendingApplications?: number; note?: string } | null>(null);
  const [applications, setApplications] = useState<AdminFoundingApplication[]>([]);
  const [status, setStatus] = useState("pending");
  const [page, setPage] = useState(1);
  const [total, setTotal] = useState(0);
  const [loading, setLoading] = useState(true);
  const [busyId, setBusyId] = useState<string | null>(null);
  const load = () => { setLoading(true); Promise.all([adminFetch<typeof summary>("/admin/founding-50"), adminFetch<{ applications: AdminFoundingApplication[]; pagination?: { total?: number } }>(`/admin/founding-50/applications?status=${status}&page=${page}&pageSize=50`)]).then(([program, applicationList]) => { setSummary(program); setApplications(applicationList.applications || []); setTotal(applicationList.pagination?.total || 0); }).catch((error) => onNotice(error.message)).finally(() => setLoading(false)); };
  useEffect(load, [status, page]);
  const updateApplication = async (application: AdminFoundingApplication, nextStatus: "approved" | "rejected") => { setBusyId(application.id); try { await adminFetch(`/admin/founding-50/applications/${encodeURIComponent(application.id)}/status`, { method: "POST", body: JSON.stringify({ status: nextStatus, notes: "Reviewed from protected Administration Center preview." }) }); onNotice(`Founding 50 application ${nextStatus}.`); load(); } catch (error) { onNotice((error as Error).message); } finally { setBusyId(null); } };
  return <section className="content-stack"><div className="page-intro"><div><p className="eyebrow">Creators</p><h2>Founding 50</h2><p>Review the existing program summary and applications. Production award activation remains owner-gated and is not exposed here.</p></div><Button variant="outline" onClick={load}><RefreshCw size={16} />Refresh</Button></div><div className="metric-grid"><Card><CardHeader><CardDescription>Program status</CardDescription><CardTitle className="metric-value">{summary?.status || (loading ? "…" : "Unavailable")}</CardTitle></CardHeader></Card><Card><CardHeader><CardDescription>Allocated</CardDescription><CardTitle className="metric-value">{summary?.allocated == null ? "Unavailable" : `${summary.allocated} / ${summary.capacity || 50}`}</CardTitle></CardHeader></Card><Card><CardHeader><CardDescription>Pending applications</CardDescription><CardTitle className="metric-value">{summary?.pendingApplications == null ? "Unavailable" : summary.pendingApplications}</CardTitle></CardHeader></Card></div><Card><CardHeader><div className="filter-bar"><select aria-label="Founding 50 application status" value={status} onChange={(event) => { setStatus(event.target.value); setPage(1); }}><option value="pending">Pending applications</option><option value="approved">Approved applications</option><option value="rejected">Rejected applications</option><option value="all">All applications</option></select><Badge variant="warning">Awards remain gated</Badge></div><CardDescription>{total} matching applications · page {page} · approve/reject uses the existing protected workflow</CardDescription></CardHeader><CardContent><p className="access-note">{summary?.note || "No program note returned."}</p><Table><TableHeader><TableRow><TableHead>Applicant</TableHead><TableHead>Status</TableHead><TableHead>Created</TableHead><TableHead>Actions</TableHead></TableRow></TableHeader><TableBody>{loading ? <TableRow><TableCell colSpan={4}><LoadingState label="Loading Founding 50 applications…" /></TableCell></TableRow> : applications.length ? applications.map((application) => <TableRow key={application.id}><TableCell><strong>{application.displayName || application.username}</strong><span className="table-subtext">@{application.username} · {application.role}</span></TableCell><TableCell><Badge variant={application.status === "approved" ? "success" : application.status === "pending" ? "warning" : "outline"}>{application.status}</Badge></TableCell><TableCell>{application.createdAt ? new Date(application.createdAt).toLocaleDateString() : "—"}</TableCell><TableCell>{application.status === "pending" ? <div className="detail-actions"><Button size="sm" disabled={busyId === application.id} onClick={() => updateApplication(application, "approved")}>Approve</Button><Button size="sm" variant="destructive" disabled={busyId === application.id} onClick={() => updateApplication(application, "rejected")}>Reject</Button></div> : <span className="table-subtext">Previously reviewed</span>}</TableCell></TableRow>) : <TableRow><TableCell colSpan={4}><EmptyState label={`No ${status} Founding 50 applications returned.`} /></TableCell></TableRow>}</TableBody></Table><div className="pagination"><span className="muted">{total} matching applications</span><div><Button size="sm" variant="outline" disabled={page <= 1} onClick={() => setPage((value) => value - 1)}>Previous</Button><Button size="sm" variant="outline" disabled={!total || page >= Math.ceil(total / 50)} onClick={() => setPage((value) => value + 1)}>Next</Button></div></div></CardContent></Card></section>;
}

